// An illustrative unordered bag, independent of community and publication date.
function hashId(id){let h=2166136261;for(const c of id){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return h>>>0;}
const shuffled=[...G.nodes].sort((a,b)=>hashId(a.id)-hashId(b.id));
const bagCoords=new Map(shuffled.map((n,i)=>{const angle=i*2.399963229728653,rad=270*Math.sqrt((i+.5)/G.nodes.length);return[n.id,{x:500+rad*Math.cos(angle),y:320+rad*Math.sin(angle)}];}));
const S='http://www.w3.org/2000/svg';function svgEl(name,attrs){const e=document.createElementNS(S,name);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);return e;}
const graphs=[];
function graph(container,mode){const svg=svgEl('svg',{viewBox:['global','frontier-overview','closing-map','title-map','origin-map'].includes(mode)?'180 0 640 640':'0 0 1000 640',class:'map-svg',role:'img','aria-label':mode==='local'?'ResearchAgent contribution neighborhood':'AI-scientist graph, 581 contribution nodes'});container.append(svg);const defs=svgEl('defs',{}),marker=svgEl('marker',{id:'checked-arrow-'+mode,markerWidth:9,markerHeight:9,refX:8,refY:4,orient:'auto',markerUnits:'userSpaceOnUse'});marker.append(svgEl('path',{d:'M0 0L8 4L0 8Z',fill:'#0a9396'}));defs.append(marker);svg.append(defs);const wrap=svgEl('g',{}),links=svgEl('g',{}),nodes=svgEl('g',{}),labels=svgEl('g',{});svg.append(wrap);wrap.append(links,nodes,labels);const local=mode==='local';const chosen=local?G.nodes.filter(n=>G.localIds.includes(n.id)):G.nodes;const ids=new Set(chosen.map(n=>n.id));const p=n=>local?{x:70+n.localX*830,y:55+(1-n.localY)*490}:coords.get(n.id);const es=new Map(),ns=new Map();
G.edges.filter(e=>e.relation!=='none'&&ids.has(e.source)&&ids.has(e.target)).forEach(e=>{const a=p(nodeMap.get(e.source)),b=p(nodeMap.get(e.target));const l=svgEl('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,class:'link','data-id':e.id});if(local&&e.id===G.checkedEdgeId){l.style.stroke='#0a9396';l.style.strokeWidth='4';l.style.strokeOpacity='1';if(local){const dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy);l.setAttribute('x2',b.x-dx/len*20);l.setAttribute('y2',b.y-dy/len*20);l.setAttribute('marker-end','url(#checked-arrow-'+mode+')');}}links.append(l);es.set(e.id,l);});
chosen.forEach(n=>{const a=p(n);const c=svgEl('circle',{cx:a.x,cy:a.y,r:local?8:4.6,fill:color(n),class:'point','data-id':n.id,tabindex:mode==='explorer'?0:-1,'aria-label':n.paperTitle+': '+n.statement});const t=svgEl('title',{});t.textContent=n.paperTitle+' — '+n.statement;c.append(t);nodes.append(c);ns.set(n.id,c);if(mode==='explorer'){c.addEventListener('click',()=>selectNode(n.id));c.addEventListener('keydown',ev=>{if(ev.key==='Enter'){ev.stopPropagation();selectNode(n.id);}});}if(local){const text=svgEl('text',{x:a.x+13,y:a.y-12,class:'graph-label','data-id':n.id});(n.localLabel||n.paperTitle).split('\n').forEach((line,j)=>{const t=svgEl('tspan',{x:a.x+13,dy:j?20:0});t.textContent=line;text.append(t);});labels.append(text);}});
const g={svg,wrap,links,nodes,labels,es,ns,mode,p};graphs.push(g);return g;}
document.querySelectorAll('[data-graph]').forEach(el=>graph(el,el.dataset.graph));
const inspectionGraph=graphs.find(g=>g.mode==='local');const inspectionContext=svgEl('g',{class:'inspection-context'});inspectionGraph.wrap.insertBefore(inspectionContext,inspectionGraph.links);G.edges.filter(e=>e.relation!=='none').forEach(e=>{const a=coords.get(e.source),b=coords.get(e.target);inspectionContext.append(svgEl('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:'#7e858d','stroke-opacity':.13,'stroke-width':.8}));});G.nodes.filter(n=>!G.localIds.includes(n.id)).forEach(n=>{const p=coords.get(n.id);inspectionContext.append(svgEl('circle',{cx:p.x,cy:p.y,r:4,fill:color(n)}));});const selectionLeaders=svgEl('g',{class:'selection-leaders'});inspectionGraph.wrap.append(selectionLeaders);
document.querySelectorAll('.legend').forEach(el=>el.innerHTML=G.communities.map(c=>`<span><i style="background:${c.color}"></i>${esc(c.label)}</span>`).join(''));
