const scoperPositions=new Map(scoperPapers.map((p,i)=>{const angle=i*2.399963229728653,r=262*Math.sqrt((i+.5)/scoperPapers.length);return[p.id,{x:500+r*Math.cos(angle),y:320+r*Math.sin(angle)}];}));
const contributionOrigins=new Map(G.nodes.map(n=>[n.id,scoperPositions.get(n.paperId)]));
const scoperPaperLayer=svgEl('g',{class:'scoper-paper-bag','aria-label':'152 retained source papers'});globalGraph.wrap.insertBefore(scoperPaperLayer,globalGraph.nodes);
scoperPapers.forEach(p=>{const q=scoperPositions.get(p.id),g=svgEl('g',{transform:`translate(${q.x} ${q.y})`,class:'scoper-paper'});g.append(svgEl('path',{d:'M-7-10H3L8-5V10H-7Z',fill:'#fffdf7',stroke:'#7e9299','stroke-width':.8}),svgEl('path',{d:'M3-10V-5H8M-4-1H4M-4 3H4M-4 6H1',fill:'none',stroke:'#a6b3b7','stroke-width':.7}));const title=svgEl('title',{});title.textContent=p.title||p.id;g.append(title);scoperPaperLayer.append(g);});
const monthOf=d=>Number(d.slice(0,4))+(Number(d.slice(5,7))-1)/12;
const firstMonth=Math.min(...G.timelinePapers.map(p=>monthOf(p.date))),lastMonth=Math.max(...G.timelinePapers.map(p=>monthOf(p.date)));
let timelineDots=[],timelinePlayhead=null;
function buildPublicationTimeline(){
 const host=document.getElementById('timeline-chart'),svg=svgEl('svg',{viewBox:'0 0 730 600',role:'img','aria-label':'Figure 1 publication timeline: one dot per retained paper, grouped by dominant community'});host.append(svg);
 const labels=['Peer review','Autonomous','Hypotheses','Benchmarks','Multi-agent','Domain agents','Idea evaluation','RAG / lit. QA','Safety / risk','Other'];
 const x=v=>220+(v-2023)/(2026.65-2023)*485,y=i=>42+i*49;
 labels.forEach((label,i)=>{if(i===0||i===2)svg.append(svgEl('rect',{x:213,y:y(i)-23,width:500,height:46,fill:i===0?'#eaf1f7':'#fbf1d9'}));const t=svgEl('text',{x:200,y:y(i)+8,'text-anchor':'end',fill:'#3b4252','font-size':24});t.textContent=label;svg.append(t);svg.append(svgEl('line',{x1:213,x2:713,y1:y(i),y2:y(i),stroke:'#e2e5ea'}));});
 [2023,2024,2025,2026].forEach(year=>{svg.append(svgEl('line',{x1:x(year),x2:x(year),y1:15,y2:510,stroke:'#d5d9df'}));const t=svgEl('text',{x:x(year),y:550,'text-anchor':'middle',fill:'#6b7686','font-size':26});t.textContent=year;svg.append(t);});
 const buckets=new Map();G.timelinePapers.forEach(p=>{const k=p.community+':'+p.date.slice(0,7);if(!buckets.has(k))buckets.set(k,[]);buckets.get(k).push(p);});
 for(const rows of buckets.values()){rows.sort((a,b)=>a.id.localeCompare(b.id)).forEach((p,i)=>{const lane=p.community<0?9:p.community;const dot=svgEl('circle',{cx:x(monthOf(p.date)),cy:y(lane)+8.8*(i-(rows.length-1)/2),r:4.9,fill:G.communities.find(c=>c.id===p.community).color,stroke:'#fff','stroke-width':.6});svg.append(dot);timelineDots.push({el:dot,month:monthOf(p.date)});});}
 timelinePlayhead=svgEl('line',{x1:x(firstMonth),x2:x(firstMonth),y1:15,y2:510,stroke:'#0a9396','stroke-width':2,'stroke-dasharray':'5 5'});svg.append(timelinePlayhead);timelinePlayhead.dataset.xmin=x(firstMonth);timelinePlayhead.dataset.xmax=x(lastMonth);
}
function setGlobalPositions(points){globalGraph.ns.forEach((el,id)=>{const p=points.get(id);el.setAttribute('cx',p.x);el.setAttribute('cy',p.y);});globalGraph.es.forEach((el,id)=>{const e=edgeMap.get(id),a=points.get(e.source),b=points.get(e.target);for(const[k,v]of Object.entries({x1:a.x,y1:a.y,x2:b.x,y2:b.y}))el.setAttribute(k,v);});}
function moveGlobal(points,animated){if(layoutFrame)cancelAnimationFrame(layoutFrame);const start=new Map([...globalGraph.ns].map(([id,el])=>[id,{x:+el.getAttribute('cx'),y:+el.getAttribute('cy')}]));if(!animated||reduce){setGlobalPositions(points);return;}const began=performance.now();function frame(now){const t=Math.min(1,(now-began)/1600),v=1-Math.pow(1-t,3),current=new Map();points.forEach((p,id)=>{const a=start.get(id);current.set(id,{x:a.x+(p.x-a.x)*v,y:a.y+(p.y-a.y)*v});});setGlobalPositions(current);if(t<1)layoutFrame=requestAnimationFrame(frame);}layoutFrame=requestAnimationFrame(frame);}
function applyMonth(cut){globalGraph.ns.forEach((el,id)=>el.style.opacity=monthOf(nodeMap.get(id).date)<=cut+1e-8?'1':'.025');globalGraph.es.forEach((el,id)=>{const e=edgeMap.get(id);el.style.opacity=Math.max(monthOf(nodeMap.get(e.source).date),monthOf(nodeMap.get(e.target).date))<=cut+1e-8?'1':'0';});timelineDots.forEach(d=>d.el.style.opacity=d.month<=cut+1e-8?'1':'.05');const x=Number(timelinePlayhead.dataset.xmin)+(cut-firstMonth)/(lastMonth-firstMonth)*(Number(timelinePlayhead.dataset.xmax)-Number(timelinePlayhead.dataset.xmin));timelinePlayhead.setAttribute('x1',x);timelinePlayhead.setAttribute('x2',x);timelinePlayhead.style.opacity=cut>=lastMonth?'0':'1';const yr=Math.floor(cut),mo=Math.min(11,Math.max(0,Math.floor((cut-yr)*12+1e-5)));document.getElementById('timeline-date').textContent=new Date(yr,mo,1).toLocaleDateString('en-GB',{month:'long',year:'numeric'});}
