function buildFrontierNative(){
 const host=document.getElementById('frontier-native'),svg=svgEl('svg',{viewBox:'0 0 1440 600',role:'img','aria-label':'Two contribution communities with publication-month radial layout and proposed dependencies'});host.append(svg);frontierView.svg=svg;
 const defs=svgEl('defs',{});for(const [id,fill] of [['cited','#3b4252'],['uncited','#3d7ea6']]){const marker=svgEl('marker',{id:'frontier-arrow-'+id,viewBox:'0 0 10 10',refX:8,refY:5,markerWidth:7,markerHeight:7,orient:'auto',markerUnits:'userSpaceOnUse'});marker.append(svgEl('path',{d:'M0 0L9 5L0 10Z',fill}));defs.append(marker);}svg.append(defs);
 const rings=svgEl('g',{class:'frontier-rings'}),links=svgEl('g',{class:'frontier-edges'}),nodes=svgEl('g',{class:'frontier-nodes'}),labels=svgEl('g',{class:'frontier-labels'});svg.append(rings,links,nodes,labels);
 function label(parent,value,x,y,attrs={}){const t=svgEl('text',{x,y,...attrs});t.textContent=value;parent.append(t);return t;}
 const selected=new Map();[...FRONTIER_DATA].reverse().forEach((panel,i)=>{const cx=i?1080:360,cy=280,radius=190;label(rings,panel.label,cx,30,{'text-anchor':'middle',class:'frontier-panel-title',fill:i?'#9b7c25':'#4a6d8c'});label(rings,panel.nodes.length+' contributions',cx,62,{'text-anchor':'middle',class:'frontier-panel-count'});
 for(let year=Math.floor(panel.tmin)+1;year<=Math.floor(panel.tmax);year++){const r=(panel.r0+(year-panel.tmin)/(panel.tmax-panel.tmin)*(1-panel.r0))*radius;rings.append(svgEl('circle',{cx,cy,r,class:'frontier-year-ring'}));label(rings,String(year),cx-r*.707,cy+r*.707,{'text-anchor':'middle',class:'frontier-year'});}
 rings.append(svgEl('circle',{cx,cy,r:radius,class:'frontier-outer-ring'}));label(rings,'earlier',cx,cy+6,{'text-anchor':'middle',class:'frontier-earlier'});
 panel.nodes.forEach(n=>selected.set(n.id,{x:cx+n.x*radius,y:cy-n.y*radius,r:n.incoming?5.8+Math.sqrt(n.incoming)*2.8:4.8,incoming:n.incoming,panel:i}));
 panel.edges.forEach(e=>{const path=svgEl('path',{class:'frontier-edge '+(e.dependency?'dependency':'other')+' '+(e.cited?'cited':'uncited'),'data-id':e.id,fill:'none'});if(e.dependency)path.setAttribute('marker-end','url(#frontier-arrow-'+(e.cited?'cited':'uncited')+')');links.append(path);frontierView.edges.set(e.id,{el:path,e});});
 });
 const contextEdges=svgEl('g',{class:'frontier-context-links'});svg.insertBefore(contextEdges,rings);G.edges.filter(e=>e.relation!=='none').forEach(e=>{const a=nodeMap.get(e.source),b=nodeMap.get(e.target);contextEdges.append(svgEl('line',{x1:350+(a.x-.005)*510/1.03,y1:305-(a.y-.005)*510/1.03,x2:350+(b.x-.005)*510/1.03,y2:305-(b.y-.005)*510/1.03}));});
 G.nodes.forEach(n=>{const p={x:350+(n.x-.005)*510/1.03,y:305-(n.y-.005)*510/1.03,r:selected.has(n.id)?5.4:3.8};frontierView.initial.set(n.id,p);frontierView.positions.set(n.id,p);const circle=svgEl('circle',{cx:p.x,cy:p.y,r:p.r,fill:color(n),'data-id':n.id,class:'frontier-dot'+(selected.has(n.id)?' selected':' context')});const title=svgEl('title',{});title.textContent=n.paperTitle+' — '+n.statement;circle.append(title);nodes.append(circle);frontierView.nodes.set(n.id,circle);});frontierView.selected=selected;
 for(const [id,name,dx,dy] of [['openalex:W4394647523::k00','HypoGeniC',-31,-35],['arxiv:2410.17309v3::k00','HypoRefine',35,37]]){const p=selected.get(id),line=svgEl('line',{x1:p.x,y1:p.y,x2:p.x+dx*.75,y2:p.y+dy*.75,class:'frontier-hub-leader'});labels.append(line);label(labels,name,p.x+dx,p.y+dy,{'text-anchor':dx<0?'end':'start',class:'frontier-hub-name'});}
 frontierView.rings=rings;frontierView.contextEdges=contextEdges;frontierView.labelsGroup=labels;

 drawFrontier(0);
}
function frontierPath(a,b,curved){const dx=b.x-a.x,dy=b.y-a.y,len=Math.max(1,Math.hypot(dx,dy));const padA=a.r+2,padB=b.r+5;const ax=a.x+dx/len*padA,ay=a.y+dy/len*padA,bx=b.x-dx/len*padB,by=b.y-dy/len*padB;return curved?`M${ax} ${ay} Q${(ax+bx)/2-dy*.10} ${(ay+by)/2+dx*.10} ${bx} ${by}`:`M${ax} ${ay} L${bx} ${by}`;}
function drawFrontier(amount){
 G.nodes.forEach(n=>{const a=frontierView.initial.get(n.id),b=frontierView.selected.get(n.id)||a,p={x:a.x+(b.x-a.x)*amount,y:a.y+(b.y-a.y)*amount,r:a.r+(b.r-a.r)*amount};frontierView.positions.set(n.id,p);const el=frontierView.nodes.get(n.id);el.setAttribute('cx',p.x);el.setAttribute('cy',p.y);el.setAttribute('r',p.r);if(!frontierView.selected.has(n.id))el.style.opacity=String(.17*(1-amount));});
 frontierView.edges.forEach(({el,e})=>el.setAttribute('d',frontierPath(frontierView.positions.get(e.source),frontierView.positions.get(e.target),e.dependency)));
}
function updateFrontier(target,instant=false){
 const slide=slides[frontierIndex].el;slide.dataset.frontierStep=target;slide.classList.toggle('frontier-open',target>=1);
 if(frontierView.state===target&&!instant)return;const old=frontierView.state;frontierView.state=target;if(frontierView.frame)cancelAnimationFrame(frontierView.frame);
 const start=old>=1?1:0,end=target>=1?1:0;if(instant||reduce||start===end){drawFrontier(end);return;}
 const began=performance.now();function frame(now){if(frontierView.state!==target)return;const t=Math.min(1,(now-began)/1450),u=t*t*(3-2*t);drawFrontier(start+(end-start)*u);if(t<1)frontierView.frame=requestAnimationFrame(frame);}
 frontierView.frame=requestAnimationFrame(frame);
}
