let workflowHandoffFrame=null;
function handoffPoints(selector){const box=root.getBoundingClientRect(),scale=box.width/1600;return new Map([...document.querySelectorAll(selector)].map(el=>{const b=el.getBoundingClientRect();return [el.dataset.handoffId||el.dataset.id,{x:(b.x+b.width/2-box.x)/scale,y:(b.y+b.height/2-box.y)/scale,r:b.width/2/scale,fill:el.getAttribute('fill')}];}));}
function workflowHandoff(from){if(reduce||!from.size)return;const to=handoffPoints('[data-graph="global"] .point');const overlay=svgEl('svg',{id:'workflow-handoff',viewBox:'0 0 1600 900'});overlay.style.cssText='position:absolute;inset:0;width:1600px;height:900px;z-index:6;pointer-events:none';const dots=[];from.forEach((a,id)=>{const el=svgEl('circle',{cx:a.x,cy:a.y,r:a.r,fill:a.fill});overlay.append(el);if(id===workflowTracedId){el.setAttribute('stroke','#0a9396');el.setAttribute('stroke-width','2');}dots.push({el,a,b:to.get(id)});});root.append(overlay);globalGraph.svg.style.opacity='0';const start=performance.now();function frame(now){const t=Math.min(1,(now-start)/1450),u=t*t*(3-2*t);if(index!==mapIndex||step!==0){overlay.remove();globalGraph.svg.style.opacity='1';return;}dots.forEach(({el,a,b})=>{if(!b)return;el.setAttribute('cx',a.x+(b.x-a.x)*u);el.setAttribute('cy',a.y+(b.y-a.y)*u);el.setAttribute('r',a.r+(b.r-a.r)*u);el.setAttribute('fill',t<.45?a.fill:'#9aa0b0');});if(t<1)workflowHandoffFrame=requestAnimationFrame(frame);else{overlay.remove();globalGraph.svg.style.opacity='1';workflowHandoffFrame=null;}}workflowHandoffFrame=requestAnimationFrame(frame);}
function render(){slides[inspectionIndex].el.dataset.caseStep=index===inspectionIndex?step+1:1;slides[inspectionIndex].el.classList.toggle('case-open',index===inspectionIndex&&step>=1);const workflowStart=visibleIndex===workflowIndex&&index===mapIndex&&step===0?handoffPoints('.workflow-real-map circle[data-handoff-id]'):null;if(workflowHandoffFrame){cancelAnimationFrame(workflowHandoffFrame);workflowHandoffFrame=null;document.getElementById('workflow-handoff')?.remove();globalGraph.svg.style.opacity='1';}updateFrontier(index===frontierIndex?step:0);const atlasStart=null;visibleIndex=index;slides[workflowIndex].el.dataset.workflowStep=index===workflowIndex?step:3;slides[representationIndex].el.classList.toggle('expanded',index===representationIndex&&step>=1);slides[representationIndex].el.classList.toggle('linked',index===representationIndex&&step>=2);slides.forEach((s,i)=>{s.el.classList.toggle('active',i===index);s.el.setAttribute('aria-hidden',i!==index);s.el.querySelectorAll('[data-step]').forEach(e=>e.classList.toggle('shown',Number(e.dataset.step)<=step));});document.getElementById('position').textContent=`${index+1} / ${slides.length} · ${step+1}/${slides[index].steps+1}`;document.title=`PRIOR · ${index+1}. ${slides[index].title}`;history.replaceState(null,'',`#${index+1}.${step}`);document.getElementById('previous').disabled=index===0&&step===0;document.getElementById('next').disabled=index===slides.length-1&&step===slides[index].steps;applyGraphStates();updateNotes();updatePresenter();if(atlasStart)morphAtlasToNeighborhood(atlasStart);if(workflowStart)workflowHandoff(workflowStart);}
function next(){if(step<slides[index].steps)step++;else if(index<slides.length-1){index++;step=0;}render();}
function previous(){if(step>0)step--;else if(index>0){index--;step=slides[index].steps;}render();}
function go(i,s=0){index=Math.max(0,Math.min(slides.length-1,i));step=Math.max(0,Math.min(slides[index].steps,s));render();}
function resize(){const scale=Math.min(innerWidth/1600,(innerHeight-48)/900);root.style.transform=`scale(${scale})`;}
function updateNotes(){const s=slides[index];document.getElementById('notes').innerHTML=`<h2>${index+1}. ${esc(s.title)}</h2><p>${s.time||'Backup / Q&A'}</p><p>${esc(s.notes)}</p><p><a href="speaker-notes.md" target="_blank">Full script and source references</a></p>`;}
function toggle(id){const el=document.getElementById(id);el.hidden=!el.hidden;}
function showOverview(){const el=document.getElementById('overview');el.innerHTML='<h2>Main talk + backup slides</h2><div class="overview-grid">'+slides.map((s,i)=>`<button data-go="${i}"><small>${s.backup?'Backup':s.time} · ${i+1}</small>${esc(s.title)}</button>`).join('')+'</div><p>Esc to close</p>';el.hidden=false;el.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{go(Number(b.dataset.go));el.hidden=true;});}
function openPresenter(){presenter=window.open('','prior-presenter','width=850,height=850');if(!presenter)return;presenter.document.write(`<!doctype html><html><head><title>PRIOR presenter</title><style>body{font:22px/1.6 'Avenir Next',sans-serif;margin:40px;color:#17243d;background:#f7f9fc}h1{font-size:30px;line-height:1.2}button{font:inherit;padding:9px 20px;margin-right:12px}#time{font-size:42px;color:#0a9396}small{color:#56657b}#copy{white-space:pre-wrap}</style></head><body><small>Share the presentation window, not this window.</small><div id="time"></div><h1 id="title"></h1><p id="timing"></p><div id="copy"></div><p id="upnext"></p><button onclick="opener.deck.previous()">Previous</button><button onclick="opener.deck.next()">Next</button><button onclick="opener.deck.resetTimer()">Reset timer</button></body></html>`);presenter.document.close();presenter.document.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key===' '){e.preventDefault();next();}if(e.key==='ArrowLeft'){e.preventDefault();previous();}});updatePresenter();}
function updatePresenter(){if(!presenter||presenter.closed)return;const d=presenter.document,s=slides[index];d.getElementById('title').textContent=`${index+1}. ${s.title} (${step+1}/${s.steps+1})`;d.getElementById('copy').textContent=s.notes;d.getElementById('timing').textContent=s.time||'Backup / Q&A';d.getElementById('upnext').textContent='Next slide: '+(slides[index+1]?.title||'End');const seconds=Math.floor((Date.now()-started)/1000);d.getElementById('time').textContent=`${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`;}
async function fullscreen(){try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen();}catch{toggle('help');}}
document.getElementById('next').onclick=next;document.getElementById('previous').onclick=previous;document.getElementById('overview-button').onclick=showOverview;document.getElementById('notes-button').onclick=()=>toggle('notes');document.getElementById('presenter-button').onclick=openPresenter;document.getElementById('fullscreen-button').onclick=fullscreen;document.getElementById('help-button').onclick=()=>toggle('help');
window.addEventListener('keydown',e=>{if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='Escape'){['overview','notes','help'].forEach(id=>document.getElementById(id).hidden=true);return;}if(!document.getElementById('overview').hidden||!document.getElementById('help').hidden)return;switch(e.key){case'ArrowRight':case' ':e.preventDefault();next();break;case'ArrowLeft':e.preventDefault();previous();break;case'PageDown':e.preventDefault();go(index+1);break;case'PageUp':e.preventDefault();go(index-1);break;case'Home':e.preventDefault();go(0);break;case'End':e.preventDefault();go(closingIndex);break;case'o':case'O':showOverview();break;case'n':case'N':toggle('notes');break;case'p':case'P':openPresenter();break;case'f':case'F':fullscreen();break;case'b':case'B':go(mainCount);break;case'?':toggle('help');break;}});
let beforePrintState=null;
window.addEventListener('resize',resize);window.addEventListener('beforeprint',()=>{slides[inspectionIndex].el.dataset.caseStep=2;slides[representationIndex].el.classList.add('expanded','linked');updateFrontier(3,true);slides[inspectionIndex].el.classList.add('case-open');slides[workflowIndex].el.dataset.workflowStep=3;document.getElementById('atlas-transition')?.remove();beforePrintState={index,step};index=mapIndex;step=4;applyGraphStates();if(timelineFrame)cancelAnimationFrame(timelineFrame);applyMonth(lastMonth);index=inspectionIndex;step=3;const savedGlobal=globalMode;globalMode=3;applyGraphStates();globalMode=savedGlobal;slides[mapIndex].el.classList.add('has-communities','has-timeline');setGlobalPositions(coords);globalGraph.ns.forEach((e,id)=>{e.style.fill=color(nodeMap.get(id));e.style.opacity='1';});globalGraph.es.forEach(e=>e.style.opacity='1');});window.addEventListener('afterprint',()=>{if(beforePrintState){index=beforePrintState.index;step=beforePrintState.step;}render();});
window.deck={go,next,previous,slides,resetTimer:()=>{started=Date.now();updatePresenter();},getState:()=>({index,step}),playTimeline,finishTimeline:()=>{if(timelineFrame)cancelAnimationFrame(timelineFrame);applyMonth(lastMonth);}};
const match=location.hash.match(/^#(\d+)\.(\d+)$/);if(match){index=Math.min(slides.length-1,Math.max(0,Number(match[1])-1));step=Math.min(slides[index].steps,Number(match[2]));}buildPublicationTimeline();document.getElementById('replay-timeline').onclick=playTimeline;resize();render();setInterval(updatePresenter,1000);
